import React, { Component } from 'react'
import axios from 'axios'
import Global from '../'

export default class EmpleadosDepartamentos extends Component {

    cajaIdDepartamentos = React.createRef()
    urlEmpleados = Global.urlApiEmpleados
    buscarEmpleado = (event) => {
        event.preventDefault()
        let idDepartamentos = this.cajaIdDepartamentos.current.value

        let request = "api/empleados/empleadosdepartamento/" + idDepartamentos
        axios.get(this.urlEmpleados + request).then((response) => {
            this.setState({
                empleados: response.data
            })
        })
    }

    state = {
        empleados: []
    }
    render() {
        return (
            <div>
                <h1>Api Empleados Departamentos</h1>
                <form>
                    <label>Introduca id departamento: </label>
                    <input type="text" ref={this.cajaIdDepartamento} />
                    <button onClick={this.buscarEmpleados}>
                        Buscar empleados
                    </button>
                </form>
                <ul>
                    {
                        this.state.empleados.map((emp, index) => {
                            return (<li key={index}>
                                {emp.apellido}, Oficio: {emp.oficio}
                            </li>)
                        })
                    }
                </ul>
            </div>
        )
    }
}
